# Dated source DAG, row identity, join allocation and amount reconciliation.
validate_source_lineage<-function(nodes,edges,joins,reconciliations,uses,contract,context=NULL){
 nn<-.vs_index(nodes,'node_id','nodes');rows<-nn$rows;ni<-nn$index;links<-.vr_rows(edges,'edges');jr<-.vs_index(joins,'join_id','joins')$rows;recs<-.vs_index(reconciliations,'reconciliation_id','reconciliations')$rows;ur<-.vs_index(uses,'use_id','uses')$rows;cfg<-.ex_object(contract,'contract');for(key in c('contract_id','version','reference')).vb_string(cfg[[key]],key);fields<-.ex_object(cfg$amount_fields,'amount_fields');for(field in names(fields)){.vb_string(field,'amount field');.vb_string(fields[[field]],'amount currency')};atol<-.vb_number(cfg$absolute_tolerance,'absolute_tolerance',0);rtol<-.vb_number(cfg$relative_tolerance,'relative_tolerance',0);required<-.ex_ids(cfg$required_node_ids,'required_node_ids');required_uses<-.ex_ids(cfg$required_use_ids,'required_use_ids');required_joins<-.ex_ids(cfg$required_join_ids,'required_join_ids',empty=TRUE);violations<-join_findings<-use_findings<-list();totals<-records<-list();issue<-function(code,unit,detail)violations[[length(violations)+1]]<<-list(code=code,unit_id=unit,detail=detail);close<-function(a,b)abs(a-b)<=atol+rtol*abs(b);object<-function(x)if(length(x))x else structure(list(),names=character())
 for(row in rows){nid<-row$node_id;if(!row$kind%in%c('SOURCE','TRANSFORM','FEATURE','TARGET','PREDICTION','DECISION')).cr_error('LINEAGE_KIND','Explicit source/transform/feature/target/prediction/decision required');for(key in c('schema_version','vintage','revision','transformation_version')).vb_string(row[[key]],key);.vs_hashes(list(node=row$content_hash),'node content_hash');observed<-.cr_data_date(row$observed_at,'node observed_at');available<-.cr_data_date(row$available_at,'node available_at');if(available<observed)issue('AVAILABILITY_PRECEDES_OBSERVATION',nid,'Node available date precedes its observation');if(row$kind=='SOURCE'){.vb_string(row$source_id,'source_id');if(!row$semantic_role%in%c('FEATURE','OUTCOME','POST_DECISION')).cr_error('LINEAGE_SOURCE_ROLE','Source requires semantic role')};data<-.vs_index(row$records,'record_id','node records');records[[nid]]<-data$index;weights<-numeric();amounts<-setNames(lapply(fields,function(f)numeric()),names(fields));for(record in data$rows){weights<-c(weights,.vb_number(record$weight,'record weight',0));values<-.ex_object(record$amounts,'record amounts');if(!setequal(names(values),names(fields))).cr_error('LINEAGE_AMOUNTS','Every node record must declare contracted fields');for(f in names(fields))amounts[[f]]<-c(amounts[[f]],.vb_number(values[[f]],'record amount'))};sums<-lapply(amounts,sum);weight<-sum(weights);if(!is.finite(weight)||any(!is.finite(unlist(sums)))).cr_error('LINEAGE_NUMERICAL','Reconciled total exceeds finite range');totals[[nid]]<-list(row_count=length(data$rows),record_ids=as.list(sort(enc2utf8(as.character(names(data$index))),method='radix')),total_weight=weight,amounts=object(sums))}
 parents<-children<-setNames(lapply(ni,function(x)character()),names(ni));seen<-character();pairkey<-function(a,b).cr_hash(list(a,b));for(e in links){a<-e$parent_id;b<-e$child_id;if(is.null(ni[[a]])||is.null(ni[[b]])).cr_error('LINEAGE_EDGE','Every edge endpoint must be supplied');key<-pairkey(a,b);if(key%in%seen).cr_error('LINEAGE_EDGE','Duplicate DAG edge');seen<-c(seen,key);parents[[b]]<-c(parents[[b]],a);children[[a]]<-c(children[[a]],b);if(ni[[a]]$available_at>ni[[b]]$available_at)issue('TRANSFORMATION_LOOKAHEAD',b,paste0(a,' was unavailable when child was produced'))};indegree<-vapply(parents,length,integer(1));queue<-sort(names(indegree)[indegree==0]);order<-character();while(length(queue)){node<-queue[1];queue<-queue[-1];order<-c(order,node);for(child in sort(children[[node]])){indegree[child]<-indegree[child]-1;if(indegree[child]==0)queue<-sort(c(queue,child))}};if(length(order)!=length(ni)).cr_error('LINEAGE_CYCLE','Lineage must be acyclic');ancestors<-list();for(nid in order){ancestors[[nid]]<-parents[[nid]];for(p in parents[[nid]])ancestors[[nid]]<-union(ancestors[[nid]],ancestors[[p]]);if(ni[[nid]]$kind=='SOURCE'&&length(parents[[nid]]))issue('SOURCE_HAS_TRANSFORM_PARENTS',nid,'A source snapshot must be a lineage root');if(ni[[nid]]$kind!='SOURCE'&&!length(parents[[nid]]))issue('UNTRACED_TRANSFORMATION',nid,'Derived node lacks a source/transform parent')}
 for(rec in recs){nid<-rec$node_id;if(is.null(ni[[nid]])).cr_error('LINEAGE_RECONCILIATION','Unknown reconciliation node');.vb_string(rec$reference,'reconciliation reference');ids<-.ex_ids(rec$expected_record_ids,'expected_record_ids',empty=TRUE);ew<-.vb_number(rec$expected_total_weight,'expected total weight',0);ea<-.ex_object(rec$expected_amounts,'expected_amounts');if(!setequal(names(ea),names(fields))).cr_error('LINEAGE_RECONCILIATION','Expected amounts must cover contracted fields');if(!identical(sort(ids),sort(as.character(names(records[[nid]])))))issue('RECONCILIATION_IDS',rec$reconciliation_id,'Expected and actual record identities differ');if(!close(totals[[nid]]$total_weight,ew))issue('RECONCILIATION_WEIGHT',rec$reconciliation_id,'Expected and actual total weight differ');for(f in names(fields)){expected<-.vb_number(ea[[f]],'expected amount');if(!close(totals[[nid]]$amounts[[f]],expected))issue('RECONCILIATION_AMOUNT',rec$reconciliation_id,paste0(f,' does not reconcile'))}};for(nid in required){if(is.null(ni[[nid]]))issue('MISSING_REQUIRED_LINEAGE_NODE',nid,'Required source/output node absent')else if(!any(vapply(recs,function(r)r$node_id==nid,logical(1))))issue('MISSING_NODE_RECONCILIATION',nid,'Required node has no independent row/weight/amount reconciliation')}
 for(join in jr){jid<-join$join_id;left<-join$left_node_id;right<-join$right_node_id;out<-join$output_node_id;if(any(!c(left,right,out)%in%names(ni))||identical(left,right)).cr_error('LINEAGE_JOIN','Distinct supplied left/right and output required');if(!all(c(pairkey(left,out),pairkey(right,out))%in%seen))issue('JOIN_DAG_CONFLICT',jid,'Both join inputs must directly parent its output');cardinality<-join$cardinality;if(!cardinality%in%c('one_to_one','one_to_many','many_to_one','many_to_many')||!join$join_type%in%c('inner','left')).cr_error('LINEAGE_JOIN','Declare cardinality and inner/left semantics');if(!identical(join$weight_contract,'LEFT_WEIGHT_ALLOCATION')||!identical(join$amount_origin,'LEFT')).cr_error('LINEAGE_JOIN','Explicit left-weight/amount allocation required');mapped<-.vs_index(join$mapping,'output_id','join mapping');ledger<-mapped$rows;oi<-mapped$index;lcounts<-table(vapply(records[[left]],function(r).vb_string(r$join_key,'left join key'),character(1)));rcounts<-table(vapply(records[[right]],function(r).vb_string(r$join_key,'right join key'),character(1)));if(cardinality%in%c('one_to_one','one_to_many')&&any(lcounts>1)||cardinality%in%c('one_to_one','many_to_one')&&any(rcounts>1))issue('JOIN_CARDINALITY',jid,'Input business-key multiplicity exceeds declared cardinality');if(!setequal(names(oi),names(records[[out]])))issue('JOIN_OUTPUT_IDENTITIES',jid,'Mapping does not cover exactly the output rows');allocated<-list();used_right<-pairs<-character()
 for(m in ledger){lid<-m$left_id;rid<-m$right_id;output<-m$output_id;allocation<-.vb_number(m$allocation_weight,'allocation_weight',0);if(is.null(records[[left]][[lid]])||(!is.null(rid)&&is.null(records[[right]][[rid]]))||is.null(records[[out]][[output]])).cr_error('LINEAGE_JOIN_MAPPING','Mapping references unknown record');key<-pairkey(lid,rid);if(key%in%pairs)issue('DUPLICATE_JOIN_PAIR',jid,'Same input pair produces multiple rows');pairs<-c(pairs,key);l<-records[[left]][[lid]];o<-records[[out]][[output]];if(is.null(rid)){if(join$join_type!='left'||l$join_key%in%names(rcounts))issue('INVALID_UNMATCHED_JOIN_ROW',jid,'Unmatched output conflicts with join keys/type')}else{used_right<-union(used_right,rid);if(l$join_key!=records[[right]][[rid]]$join_key)issue('JOIN_KEY_MISMATCH',jid,'Joined rows have different business keys')};allocated[[lid]]<-if(is.null(allocated[[lid]]))allocation else allocated[[lid]]+allocation;if(!close(o$weight,l$weight*allocation))issue('JOIN_WEIGHT_MULTIPLICATION',jid,paste0(output,' weight differs from explicit left allocation'));for(f in names(fields))if(!close(o$amounts[[f]],l$amounts[[f]]*allocation))issue('JOIN_AMOUNT_MULTIPLICATION',jid,paste0(output,'/',f,' differs from left allocation'))}
 for(lid in names(allocated))if(!close(allocated[[lid]],1))issue('JOIN_ALLOCATION_NOT_CONSERVING',jid,paste0(lid,' allocations do not sum to one'));excluded<-sort(setdiff(names(records[[left]]),names(allocated)));unmatched<-sort(setdiff(names(records[[right]]),used_right));se<-sort(.ex_ids(join$excluded_left_ids,'excluded_left_ids',empty=TRUE));su<-sort(.ex_ids(join$unmatched_right_ids,'unmatched_right_ids',empty=TRUE));sameids<-function(a,b)length(a)==length(b)&&all(a==b);if(!sameids(excluded,se)||!sameids(unmatched,su))issue('JOIN_EXCLUSION_RECONCILIATION',jid,'Declared excluded/unmatched rows do not match actual mapping');if(join$join_type=='left'&&length(excluded))issue('LEFT_JOIN_DROPPED_ROWS',jid,'Left join must retain each left row');expected_pairs<-character();for(lid in names(records[[left]]))for(rid in names(records[[right]]))if(records[[left]][[lid]]$join_key==records[[right]][[rid]]$join_key)expected_pairs<-c(expected_pairs,pairkey(lid,rid));if(!all(expected_pairs%in%pairs))issue('INCOMPLETE_JOIN_MATCHES',jid,'Declared equality join omitted matching input pairs');join_findings[[length(join_findings)+1]]<-list(join_id=jid,left_rows=length(records[[left]]),right_rows=length(records[[right]]),output_rows=length(records[[out]]),excluded_left_ids=as.list(excluded),unmatched_right_ids=as.list(unmatched),allocated_left_weights=object(allocated[sort(names(allocated))]))}
 for(use in ur){uid<-use$use_id;nid<-use$node_id;if(is.null(ni[[nid]])).cr_error('LINEAGE_USE','Unknown use node');purpose<-use$purpose;if(!purpose%in%c('FEATURE','TARGET','PREDICTION','DECISION')).cr_error('LINEAGE_USE','Explicit use purpose required');asof<-.cr_data_date(use$as_of,'use as_of');known<-.cr_data_date(use$known_at,'use known_at');if(known<asof)issue('USE_KNOWLEDGE_BEFORE_ASOF',uid,'Audit knowledge cutoff precedes observation cutoff');lineage<-union(ancestors[[nid]],nid);sources<-sort(Filter(function(n)ni[[n]]$kind=='SOURCE',lineage));expected<-object(setNames(lapply(sources,function(n)ni[[n]]$content_hash),sources));supplied<-.vs_hashes(use$source_snapshot_hashes,'use source_snapshot_hashes',empty=TRUE);if(!length(sources)||!identical(.cr_hash(supplied),.cr_hash(expected)))issue('SOURCE_SNAPSHOT_BINDING',uid,'Use does not bind exactly to its historical source snapshots');for(n in sort(lineage)){if(.cr_data_date(ni[[n]]$available_at,'node available')>known)issue('SOURCE_USE_LOOKAHEAD',uid,paste0(n,' was unavailable at use knowledge cutoff'));if(purpose!='TARGET'&&.cr_data_date(ni[[n]]$observed_at,'node observed')>asof)issue('FUTURE_OBSERVATION_IN_FEATURE_PATH',uid,paste0(n,' observation follows original as-of'));if(purpose!='TARGET'&&(ni[[n]]$kind=='TARGET'||isTRUE(ni[[n]]$semantic_role%in%c('OUTCOME','POST_DECISION'))))issue('OUTCOME_IN_PREDICTIVE_PATH',uid,paste0(n,' carries target/post-decision evidence'))};use_findings[[length(use_findings)+1]]<-list(use_id=uid,node_id=nid,source_node_ids=as.list(sources),ancestor_count=length(lineage)-1)}
 for(kind in c('USE','JOIN')){required_ids<-if(kind=='USE')required_uses else required_joins;actual_ids<-if(kind=='USE')vapply(ur,function(u)u$use_id,character(1))else vapply(jr,function(j)j$join_id,character(1));for(identity in required_ids)if(!identity%in%actual_ids)issue(paste0('MISSING_REQUIRED_',kind),identity,'Required dated use/join audit absent')}
 payload<-list(contract=cfg,applicability='APPLICABLE',node_totals=object(totals),topological_order=as.list(order),join_findings=join_findings,use_findings=use_findings,metrics=list(nodes=length(rows),edges=length(links),joins=length(jr),reconciliations=length(recs),dated_uses=length(ur)),source_content_authenticated=FALSE);.vs_finish('validate_source_lineage',payload,violations,list(nodes=rows,edges=links,joins=jr,reconciliations=recs,uses=ur,contract=cfg),context)
}
